WITH filtered_subscriptions AS (SELECT * FROM subscriptions WHERE monthly_fee >= 110), summary AS (SELECT CASE WHEN status IN ('ACTIVE', 'EXPIRED') THEN 'group_a' ELSE 'other' END AS status_group, SORT_ARRAY(COLLECT_SET(status)) AS status_list FROM filtered_subscriptions GROUP BY CASE WHEN status IN ('ACTIVE', 'EXPIRED') THEN 'group_a' ELSE 'other' END) SELECT status_group, status_list FROM summary ORDER BY status_group DESC;
